let theShader;
let canvas;
let f;
let textGraphic;

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/1686762/files/vert.glsl', 'frag.glsl');
	f = loadFont(
    "https://cdnjs.cloudflare.com/ajax/libs/topcoat/0.8.0/font/SourceCodePro-Bold.otf"
  );
}

function setup() {
  pixelDensity(2);
  canvas = createCanvas(1000,1000, WEBGL);
	background(0);
	noStroke();
	shader(theShader);

	textGraphic = createGraphics(1000, 1000, WEBGL);
	textGraphic.pixelDensity(2);
	textGraphic.background(0);
	textGraphic.textFont(f);
	textGraphic.textSize(100);
	textGraphic.textAlign(LEFT, CENTER);
	textGraphic.fill("#ffffff");
	textGraphic.text("Halftone", -450, 300);
	textGraphic.text("square", -450, 400);
}

function draw() {
  theShader.setUniform("u_resolution", [width*2, height*2]);
  theShader.setUniform("u_time", millis() / 1000.0);
  theShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0)]);
	theShader.setUniform("u_text", textGraphic);

  rect(width * -0.5, height * -0.5, width, height);
}

// === Tab: frag.glsl ===
#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform float u_time;
uniform vec2 u_mouse;
uniform sampler2D u_text;

float rand(vec2 co){
  return fract(sin(dot(co.xy,vec2(12.9898,78.233))) * 43758.5453);
}

float smin(float d1, float d2, float k) {
    return -log(exp(-k * d1) + exp(-k * d2)) / k;
}

void main() {
	vec2 uv = gl_FragCoord.xy / u_resolution.xy;
	vec2 mouse = u_mouse / u_resolution.xy;
	mouse = (mouse-.5) * 2.;

	vec2 gv = fract(uv * 30. + .25);

	float box1 = distance(gv, vec2(0., 1.));
	float box3 = distance(gv, vec2(1., 1.));
	float box5 = distance(gv, vec2(.5, .5));
	float box7 = distance(gv, vec2(.0, .0));
	float box9 = distance(gv, vec2(1., 0.));

	float box2 = distance(gv, vec2(.5, 1.));
	float box4 = distance(gv, vec2(.0, .5));
	float box6 = distance(gv, vec2(1., .5));
	float box8 = distance(gv, vec2(.5, .0));

	float k = 32.;

	float b; 
	b = smin(box2, box4, k);
	b = smin(b, box6, k);
	b = smin(b, box8, k);

	float br;
	br = smin(box1, box3, k);
	br = smin(br, box5, k);
	br = smin(br, box7, k);
	br = smin(br, box9, k);


	b = smin(b, 1.-br, 1.);

	// -0.47 ~ 0.03 => 0 ~ 1
	b = (b + .47) * 2.;

	b += rand(uv) * .02 - .01;

	float threshold = sin(u_time - (uv.x*2.)) * .5 + .5;
	float threshold2 = sin(u_time - (uv.y*5.)) * .5 + .5;
	threshold = mix(threshold, threshold2, .5);

	float m = 1. - distance(uv, mouse + vec2(1.)) * 5.;
	m = max(0., m);
	m *= step(m, 1.);

	threshold = threshold + m - 2. * threshold * m;

	float s = step(b, threshold);

	float c = s;

	vec2 text_uv = uv;
	text_uv.y = 1.-text_uv.y;
	float text = texture2D(u_text, text_uv).r;
	text = step(.5, text);
	c = c + text - 2. * c * text;


	vec3 color1 = vec3(1., .92, .98);
	vec3 color2 = vec3(0., .3, .24);

	vec3 col = mix(color1, color2, c);

  gl_FragColor = vec4(col,1.0); 
}

